56	    // Andes V5 CSR block (v3). HYBRID_ANDES_CSR_LIST is the shared source of
57	    // truth; a NULL handle (non-Andes stub) drains 0 -> tolerant no-op.
58	#define HYBRID_ANDES_FIELD(field, addr, name) \
59	    struct qemu_plugin_register *andes_##field;
60	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
61	#undef HYBRID_ANDES_FIELD
62	    struct qemu_plugin_register *pmacfg[HYBRID_PMA_CFG_NUM];
