159	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
160	{
161	    for (guint i = 0; i < regs->len; i++) {
162	        qemu_plugin_reg_descriptor *rd =
163	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
164	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
165	            return rd->handle;
166	        }
167	    }
168	    return NULL;
169	}
