171	// Lazily resolves register handles. The plugin's vcpu_init runs before
172	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
173	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
174	// regs at that moment. By the time the entry trigger fires, all dynamic
175	// features are registered and a fresh call returns the full list.
176	static void resolve_handles(VcpuRegs *v)
177	{
178	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
179	    for (int i = 0; i < 32; i++) {
180	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
181	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
182	    }
183	    v->fcsr = find_reg(regs, "fcsr");
184	    v->pc = find_reg(regs, "pc");
185	    v->priv = find_reg(regs, "priv");
186	
187	    v->mstatus  = find_reg(regs, "mstatus");
188	    v->mepc     = find_reg(regs, "mepc");
189	    v->mtvec    = find_reg(regs, "mtvec");
190	    v->mcause   = find_reg(regs, "mcause");
191	    v->mtval    = find_reg(regs, "mtval");
192	    v->mscratch = find_reg(regs, "mscratch");
193	    v->medeleg  = find_reg(regs, "medeleg");
194	    v->mideleg  = find_reg(regs, "mideleg");
195	    v->mip      = find_reg(regs, "mip");
196	    v->mie      = find_reg(regs, "mie");
197	    v->mcycle   = find_reg(regs, "mcycle");
198	    v->minstret = find_reg(regs, "minstret");
199	    v->satp     = find_reg(regs, "satp");
200	
201	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
202	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
203	
204	    char buf[16];
205	
206	    // Andes V5 CSR block (v3): resolve by gdb mnemonic from the shared X-macro.
207	#define HYBRID_ANDES_FIELD(field, addr, name) v->andes_##field = find_reg(regs, name);
208	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
209	#undef HYBRID_ANDES_FIELD
210	
211	    // M-ext CSR block (v4): resolve by gdb mnemonic (NULL if the stub does not
212	    // advertise it for the paired cpu).
213	#define HYBRID_M_EXT_FIELD(field, addr, name) v->m_ext_##field = find_reg(regs, name);
214	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
215	#undef HYBRID_M_EXT_FIELD
216	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
217	        // RV64 packs 8 PMA entries per cfg CSR, so only even cfg CSRs exist.
218	        g_snprintf(buf, sizeof(buf), "pmacfg%d", 2 * i);
219	        v->pmacfg[i] = find_reg(regs, buf);
220	    }
221	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
222	        g_snprintf(buf, sizeof(buf), "pmaaddr%d", i);
223	        v->pmaaddr[i] = find_reg(regs, buf);
224	    }
225	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
226	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
227	        v->pmpcfg[i] = find_reg(regs, buf);
228	    }
229	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
230	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
231	        v->pmpaddr[i] = find_reg(regs, buf);
232	    }
233	
234	    v->vstart = find_reg(regs, "vstart");
235	    v->vxsat  = find_reg(regs, "vxsat");
236	    v->vxrm   = find_reg(regs, "vxrm");
237	    v->vcsr   = find_reg(regs, "vcsr");
238	    v->vtype  = find_reg(regs, "vtype");
239	    v->vl     = find_reg(regs, "vl");
240	    v->vlenb  = find_reg(regs, "vlenb");
241	    for (int i = 0; i < 32; i++) {
242	        g_snprintf(buf, sizeof(buf), "v%d", i);
243	        v->vreg[i] = find_reg(regs, buf);
244	    }
245	}
