247	static uint64_t read_reg64(struct qemu_plugin_register *h)
248	{
249	    if (!h) return 0;
250	    g_autoptr(GByteArray) buf = g_byte_array_new();
251	    int sz = qemu_plugin_read_register(h, buf);
252	    if (sz <= 0) return 0;
253	    uint64_t v = 0;
254	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
255	    return v;
256	}
