258	// Reads up to `dst_max` bytes from a register handle. Returns the byte
259	// count written (0 on failure or NULL handle). Used for vector regs whose
260	// width = vlenb bytes.
261	static size_t read_reg_bytes(struct qemu_plugin_register *h,
262	                             uint8_t *dst, size_t dst_max)
263	{
264	    if (!h || dst_max == 0) return 0;
265	    g_autoptr(GByteArray) buf = g_byte_array_new();
266	    int sz = qemu_plugin_read_register(h, buf);
267	    if (sz <= 0) return 0;
268	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
269	    memcpy(dst, buf->data, n);
270	    return n;
271	}
