314	// Drain CPU state into `*s`. pc is computed by the caller (from a
315	// HandoffSite for trigger paths).
316	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
317	                             struct hybrid_state_v1 *sp)
318	{
319	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
320	    resolve_handles(v);
321	    memset(sp, 0, sizeof(*sp));
322	    struct hybrid_state_v1 s = {0};
323	    s.magic   = HYBRID_STATE_MAGIC;
324	    s.version = HYBRID_STATE_VERSION;
325	    s.flags   = HYBRID_FLAG_RV64;
326	    s.hart_id = vcpu_idx;
327	    // L6: real privilege at the boundary; M-mode fallback only when the
328	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
329	    // reads as 0 = U, which would silently demote the hart).
330	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
331	    s.pc      = pc;
332	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
333	
334	    // Floating-point: only set FP flag if at least one handle was bound,
335	    // i.e. QEMU advertised the FPU feature (D extension).
336	    int has_fp = 0;
337	    for (int i = 0; i < 32; i++) {
338	        s.fpr[i] = read_reg64(v->fpr[i]);
339	        if (v->fpr[i]) has_fp = 1;
340	    }
341	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
342	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
343	
344	    s.mstatus  = read_reg64(v->mstatus);
345	    s.mepc     = read_reg64(v->mepc);
346	    s.mtvec    = read_reg64(v->mtvec);
347	    s.mcause   = read_reg64(v->mcause);
348	    s.mtval    = read_reg64(v->mtval);
349	    s.mscratch = read_reg64(v->mscratch);
350	    s.medeleg  = read_reg64(v->medeleg);
351	    s.mideleg  = read_reg64(v->mideleg);
352	    s.mip      = read_reg64(v->mip);
353	    s.mie      = read_reg64(v->mie);
354	    s.mcycle   = read_reg64(v->mcycle);
355	    s.minstret = read_reg64(v->minstret);
356	    s.satp     = read_reg64(v->satp);
357	
358	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
359	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
360	    s.mcache_ctl = read_reg64(v->mcache_ctl);
361	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
362	
363	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
364	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
365	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
366	    // handle on a non-Andes stub reads back as 0 -> tolerant.
367	    int has_andes = 0;
368	#define HYBRID_ANDES_FIELD(field, addr, name)  \
369	    s.andes.field = read_reg64(v->andes_##field); \
370	    if (v->andes_##field) has_andes = 1;
371	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
372	#undef HYBRID_ANDES_FIELD
373	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
374	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
375	        if (v->pmacfg[i]) has_andes = 1;
376	    }
377	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
378	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
379	        if (v->pmaaddr[i]) has_andes = 1;
380	    }
381	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
382	
383	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
384	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
385	    // reads 0. The vsim caps gate decides which of these the cycle engine
386	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
387	    int has_m_ext = 0;
388	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
389	    s.m_ext.field = read_reg64(v->m_ext_##field); \
390	    if (v->m_ext_##field) has_m_ext = 1;
391	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
392	#undef HYBRID_M_EXT_FIELD
393	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
394	
395	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
396	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
397	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
398	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
399	
400	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
401	    // bounds the per-register byte count copied into vreg[]. The policy
402	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
403	    // handle truthiness so we don't conflate "stub missing vlenb" with
404	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
405	    s.vstart = read_reg64(v->vstart);
406	    s.vxsat  = read_reg64(v->vxsat);
407	    s.vxrm   = read_reg64(v->vxrm);
408	    s.vcsr   = read_reg64(v->vcsr);
409	    s.vtype  = read_reg64(v->vtype);
410	    s.vl     = read_reg64(v->vl);
411	    s.vlenb  = read_reg64(v->vlenb);
412	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
413	                       || v->vtype || v->vl);
414	    if (!has_other_v) {
415	        for (int i = 0; i < 32; i++)
416	            if (v->vreg[i]) { has_other_v = 1; break; }
417	    }
418	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
419	        v->vlenb != NULL, has_other_v, s.vlenb);
420	    if (vpol == HYBRID_V_DRAIN_ABORT) {
421	        if (v->vlenb == NULL)
422	            fprintf(stderr,
423	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
424	                    "vlenb; refusing to drain partial V state\n");
425	        else
426	            fprintf(stderr,
427	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
428	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
429	                    "truncate V registers\n",
430	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
431	                    8 * HYBRID_VLEN_BYTES_MAX);
432	        exit(2);
433	    }
434	    if (vpol == HYBRID_V_DRAIN_OK) {
435	        s.flags |= HYBRID_FLAG_V;
436	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
437	         * full live register fits the wire-format slot -- no clamp (L11). */
438	        for (int i = 0; i < 32; i++)
439	            (void) read_reg_bytes(v->vreg[i],
440	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
441	                                  (size_t) s.vlenb);
442	    }
443	
444	    // v6: which mask-governed CSRs the guest actually wrote (translate-time
445	    // decode + exec callbacks above). ucode rides transport-always: DSP
446	    // instructions update its sticky OV flag without any CSR instruction, so
447	    // instruction-level tracking cannot see those writes (like fcsr's fflags).
448	    s.write_mask[0] = __atomic_load_n(&csr_write_mask[0], __ATOMIC_RELAXED);
449	    s.write_mask[1] = __atomic_load_n(&csr_write_mask[1], __ATOMIC_RELAXED);
450	    hybrid_wm_set(s.write_mask, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_ucode);
451	    s.flags |= HYBRID_FLAG_WRITE_MASK;
