453	    // v5: L2C MMIO register window (DS220 11.8.5 Table 112, offsets
454	    // 0x0000..0x0527). Read the whole documented block from the L2C base by
455	    // PHYSICAL address (paging is off in the M-mode boot flow, so VA==PA anyway).
456	    // QEMU's AE350 machine maps L2C as a device region; if the read fails (a
457	    // machine without an L2C), the flag stays clear and consumers skip the
458	    // block. Little-endian native host, so the raw bytes land directly in
459	    // s.l2c.reg[]. The vsim side gates restore on its OWN L2C presence, so
460	    // setting the flag whenever QEMU can read the region is correct.
461	    {
462	        g_autoptr(GByteArray) l2c = g_byte_array_new();
463	        enum qemu_plugin_hwaddr_operation_result r =
