465	                                           HYBRID_L2C_REG_WINDOW_BYTES);
466	        if (r == QEMU_PLUGIN_HWADDR_OPERATION_OK
467	            && l2c->len == HYBRID_L2C_REG_WINDOW_BYTES) {
