476	// LM sidecar drain: read `size` bytes of local memory at physical `base`
477	// (the slave-port aperture) into "<state_path><suffix>". Failure is as hard
478	// an error as a failed state write: the caller asked for this memory
479	// (size > 0), so a missing/short sidecar must not masquerade as a clean
480	// handoff -- the vsim leg would silently resume with an empty ILM/DLM,
481	// exactly the bug this transport exists to fix.
482	static void drain_lm_sidecar(const char *state_path, const char *suffix,
483	                             uint64_t base, uint64_t size)
484	{
485	    if (size == 0) return;
486	    g_autofree char *path = g_strdup_printf("%s%s", state_path, suffix);
487	    g_autoptr(GByteArray) buf = g_byte_array_new();
488	    enum qemu_plugin_hwaddr_operation_result r =
489	        qemu_plugin_read_memory_hwaddr(base, buf, size);
490	    if (r != QEMU_PLUGIN_HWADDR_OPERATION_OK || buf->len != size) {
491	        fprintf(stderr,
492	                "hybrid_handoff: cannot read %" PRIu64 " bytes of local "
493	                "memory at %#" PRIx64 " (result %d)\n", size, base, (int) r);
494	        exit(2);
495	    }
496	    if (write_blob_atomic(buf->data, buf->len, path) != 0) {
497	        fprintf(stderr, "hybrid_handoff: failed to write %s\n", path);
498	        exit(2);
499	    }
500	}
