538	// Marker sites. The marker is an architectural NOP, so the pre-execution
539	// state equals the post-retire state and the window resumes AFTER it
540	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
541	// the exec callback can lag the actual current insn when V instructions
542	// retire just before the trigger -- TCG defers PC writes for performance).
543	static void on_handoff(unsigned int vcpu_idx, void *udata)
544	{
545	    const HandoffSite *site = (const HandoffSite *) udata;
546	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
547	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
548	}
549	
550	// pc boundary sites. Exec callbacks fire BEFORE the insn
551	// executes, and the boundary insn is real user code (unlike a marker NOP):
552	// the drained state must resume AT the boundary so the insn executes inside
553	// the vsim window rather than on neither leg. (Skipping it corrupts the
554	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
555	// set and the first vector op of the window faults.)
556	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
557	{
558	    const HandoffSite *site = (const HandoffSite *) udata;
559	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
560	    handoff_drain(vcpu_idx, site->vaddr);
561	}
